import json

def build_output2():
    grid = [[0]*16 for _ in range(16)]
    for row in range(16):
        # Add 6-9-8 only for rows 0-11 (matching input pattern)
        if row <= 11:
            for offset, val in [(0, 6), (1, 9), (2, 8)]:
                col = (row + 4 + offset) % 16
                grid[row][col] = val

        # Add 5 for rows 9-15 continuing the diagonal
        if row >= 9:
            grid[row][row - 9] = 5

    return grid

output = build_output2()
print(json.dumps(output))

